@app.get("/payroll/forms/{form_id}/view", response_class=HTMLResponse)
def view_employee_w2_form(
    request: Request,
    form_id: str,
    db: Session = Depends(get_db)
):
    user = get_session_user(request)
    if not user:
        return RedirectResponse(url="/login")

    tax_form = db.query(TaxRecord).filter(TaxRecord.id == form_id, TaxRecord.employee_id == user.employee_id).first()
    if not tax_form:
        raise HTTPException(status_code=404, detail="Tax form not found")

    return templates.TemplateResponse("w2_view.html", {"request": request, "form": tax_form})
